@Test
public void testRetryAndUnrecoverable() throws IOException {
    BlockFetchingListener listener = mock(BlockFetchingListener.class);
    List<? extends Map<String, Object>> interactions = Arrays.asList(// b0's IOException will trigger retry, subsequent messages will be ignored.
    ImmutableMap.<String, Object>builder().put("b0", new IOException()).put("b1", new RuntimeException()).put("b2", block2).build(), // Next, b0 is successful, b1 errors unrecoverably, and b2 triggers a retry.
    ImmutableMap.<String, Object>builder().put("b0", block0).put("b1", new RuntimeException()).put("b2", new IOException()).build(), // b2 succeeds in its last retry.
    ImmutableMap.<String, Object>builder().put("b2", block2).build());
    performInteractions(interactions, listener);
    verify(listener, timeout(5000)).onBlockFetchSuccess("b0", block0);
    verify(listener, timeout(5000)).onBlockFetchFailure(eq("b1"), (Throwable) any());
    verify(listener, timeout(5000)).onBlockFetchSuccess("b2", block2);
    verifyNoMoreInteractions(listener);
}

